"""Render docs/SCHEMAS.md from the code (single source of truth: the pydantic models)."""

from __future__ import annotations

import json

from service015.api.schemas import ParticipantStatus
from service015.models import TemplateBody
from service015.resolver import ResolvedIdentity


def _block(model) -> str:
    return "```json\n" + json.dumps(model.model_json_schema(), indent=2, sort_keys=True) + "\n```\n"


def render() -> str:
    return (
        "# Service 015 schemas\n\n"
        "Generated by `scripts/gen_schemas.py` from the pydantic models; do not edit by hand "
        "(a test fails when this file is stale).\n\n"
        "## Template schema (TemplateBody, stored per immutable version)\n\n"
        "A Template is a reusable archetype. `allowed_overrides` lists the flat dotted keys an Identity may override; "
        "`required_instance_fields` must be supplied at instantiation.\n\n"
        + _block(TemplateBody)
        + "\n## Identity instance schema (ResolvedIdentity)\n\n"
        "The deterministic snapshot of Template version + overrides. It is bound to the exact template version used and "
        "carries `resolved_hash`; `participant_identity` and `default_room` equal the identity_id.\n\n"
        + _block(ResolvedIdentity)
        + "\n## Participant status schema (ParticipantStatus)\n\n"
        "Presence is one of READY, STARTING, BUSY, ERROR, OFFLINE.\n\n"
        + _block(ParticipantStatus)
    )
